From c751a7c19c2c958a6afc1bedf1b1cb4f9cc318f7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:11:30 +0100
Subject: [PATCH] faces/grid: show text sensors without a chart

The Grid face used the chart face for every sensor, so text sensors got
an empty chart. Cells now wait for the sensor metadata and use the text
face for strings, and SensorDataModel is not ready until QML sets it up.

BUG: 521257
---
 faces/facepackages/facegrid/contents/ui/FaceGrid.qml | 12 ++++++++++--
 sensors/SensorDataModel.cpp                          |  5 +++++
 2 files changed, 15 insertions(+), 2 deletions(-)

diff --git a/faces/facepackages/facegrid/contents/ui/FaceGrid.qml b/faces/facepackages/facegrid/contents/ui/FaceGrid.qml
index b63c8522..41bfd97d 100644
--- a/faces/facepackages/facegrid/contents/ui/FaceGrid.qml
+++ b/faces/facepackages/facegrid/contents/ui/FaceGrid.qml
@@ -44,10 +44,15 @@ GridLayout {
         }
     }

+    Sensors.SensorDataModel {
+        id: sensorsModel
+        sensors: root.controller.highPrioritySensorIds
+    }
+
     Repeater {
         id: gridRepeater

-        model: root.controller.highPrioritySensorIds
+        model: sensorsModel.ready ? root.controller.highPrioritySensorIds : []

         FaceControl {
             Layout.fillWidth: true
@@ -57,7 +62,10 @@ GridLayout {
             compact: grid.compact
             controller: root.controller
             sensors: [modelData]
-            faceId: root.controller.faceConfiguration.faceId
+            faceId: isTextSensor ? "org.kde.ksysguard.textonly" : root.controller.faceConfiguration.faceId
+
+            // 10 is QMetaType::QString
+            readonly property bool isTextSensor: sensorsModel.headerData(sensorsModel.column(modelData), Qt.Horizontal, Sensors.SensorDataModel.Type) === 10
         }
     }
 }
diff --git a/sensors/SensorDataModel.cpp b/sensors/SensorDataModel.cpp
index e82ead41..598e7d3d 100644
--- a/sensors/SensorDataModel.cpp
+++ b/sensors/SensorDataModel.cpp
@@ -356,6 +356,10 @@ void KSysGuard::SensorDataModel::resetUpdateRateLimit()

 bool KSysGuard::SensorDataModel::isReady() const
 {
+    if (d->usedByQml && !d->componentComplete) {
+        return false;
+    }
+
     return d->sensors.size() == d->sensorInfos.size();
 }

@@ -386,6 +390,7 @@ void KSysGuard::SensorDataModel::componentComplete()
     d->sensorsChanged();

     Q_EMIT sensorsChanged();
+    Q_EMIT readyChanged();
 }

 void SensorDataModel::Private::addSensor(const QString &id)
-- 
2.53.0
